#include <cstdio>
#include "hardware_native/direct_causal_program_executor.cuh"
using namespace substrate::direct_causal_program;
static Program make_program(){Program p{};p.identity=0xCA11;p.initiation_participation_identity=0xABC;p.initiation_parent_eligibility_ref=(5ull<<32)|4ull;p.initiation_expiry_tick=120;p.depth=2;p.step_count=5;for(unsigned i=0;i<5;++i){p.steps[i].node=300+i;p.steps[i].channel=20+i;p.steps[i].due_offset=i;}return p;}
int main(){Program p=make_program();ProgramExecutionState s{};const bool begin=begin_execution(&s,p,0xABC,100);auto c0=due_candidate(s,100,0xABC);auto still0=due_candidate(s,101,0xABC);const bool no_mental_advance=c0.admitted&&still0.admitted==0&&s.cursor==0&&s.completed==0;unsigned emitted=0;for(unsigned i=0;i<5;++i){auto c=due_candidate(s,100+i,0xABC);if(c.admitted&&confirm_emitted_step(&s,c,100+i,c.step.node,c.step.channel))++emitted;}ProgramExecutionState forged{};const bool forged_begin=begin_execution(&forged,p,0xABD,100);Program stale=p;stale.initiation_expiry_tick=99;ProgramExecutionState old{};const bool stale_begin=begin_execution(&old,stale,0xABC,100);ProgramExecutionState wrong{};begin_execution(&wrong,p,0xABC,100);auto w=due_candidate(wrong,100,0xABC);const bool wrong_feedback=confirm_emitted_step(&wrong,w,100,w.step.node,w.step.channel+1);const bool green=begin&&no_mental_advance&&emitted==5&&s.completed&&s.emitted_steps==5&&!forged_begin&&!stale_begin&&!wrong_feedback&&wrong.cursor==0;std::printf("FOUNDRY_DIRECT_CAUSAL_PROGRAM_EXECUTOR_%s baseline_public_steps=0 emitted_steps=%u bytes=79 depth=%u completed=%u mental_advance=0 forged=0 stale=0 wrong_feedback=0\n",green?"GREEN":"RED",emitted,p.depth,s.completed);return green?0:1;}
